/* @lc app=leetcode id=2311 lang=kotlin */ class Solution { fun longestSubsequence(s: String, k: Int): Int = s.reversed().fold(Triple(0L, 0, 0)) { t, char -> if (char == '0') Triple(t.first, if (t.second < 31) t.second + 1 else 32, t.third + 1) else if (t.second < 31 && t.first + (1L shl t.second) <= k) Triple(t.first + (1L shl t.second), t.second + 1, t.third + 1) else Triple(t.first, if (t.second < 31) t.second + 1 else 32, t.third) }.third }